// Create a server that has a route that matches the path /comments that accepts a POST request and returns a JSON object with the following key-value pairs:
// key: message value: 'Comment created successfully'
// key: id value: a unique identifier generated by the server (use the nanoid library)
// The server should listen on the port given by the PORT environment variable. If PORT is not set, the server should listen on port 4001.

const express = require('express');
const { nanoid } = require('nanoid');
const app = express();

app.use(express.json());

app.post('/comments', (req, res) => {
    const { message } = req.body;
    res.json({ message: 'Comment created successfully', id: nanoid() });
});

const PORT = process.env.PORT || 4001;
app.listen(PORT, () => {
    console.log(`Server is listening on port ${PORT}`);
});

// test with
// curl -X POST -H "Content-Type: application/json" -d '{"message": "hello"}' http://localhost:4001/comments
